use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let count = Arc::new(Mutex::new(0));
    let mut handles = Vec::new();
    for _ in 0..3 {
        let count = Arc::clone(&count);
        handles.push(thread::spawn(move || {
            *count.lock().unwrap() += 2;
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    println!("{}", count.lock().unwrap());
}

