use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    let mut handles = Vec::new();
    for id in 1..=3 {
        let tx = tx.clone();
        handles.push(thread::spawn(move || {
            tx.send(id * 10).unwrap();
        }));
    }
    drop(tx);
    for h in handles {
        h.join().unwrap();
    }
    let mut all: Vec<i32> = rx.iter().collect();
    all.sort();
    println!("{all:?}");
}

use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let list = Arc::new(Mutex::new(Vec::new()));
    let mut handles = Vec::new();
    for i in 1..=3 {
        let list = Arc::clone(&list);
        handles.push(thread::spawn(move || {
            list.lock().unwrap().push(i * i);
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    let mut v = list.lock().unwrap().clone();
    v.sort();
    println!("{v:?} {}", Arc::strong_count(&list));
}
